@Component("benchmark-entity-projector")
public class BenchmarkEntityProjector implements EntityProjector<Benchmark>{
		
	// core constructor
	public BenchmarkEntityProjector(ProjectorRegistry registry,
										BenchmarkRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Benchmark> getEntityClass() {
		return Benchmark.class;
	}

    /*
	 * Insert a Benchmark
	 * 
     * @param	entity Benchmark
     */
    public Benchmark create( Benchmark entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Benchmark
	 * 
     * @param	entity Benchmark
     */
    public Benchmark update( Benchmark entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Benchmark
	 * 
     * @param	id		UUID
     */
    public Benchmark delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Benchmark entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    


    /*
     * Add to the PerformanceReports
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Benchmark
     */
    public Benchmark addToPerformanceReports( UUID parentId, PerformanceReport addTo ) {
	    LOGGER.info("handling AssignPerformanceReportsToBenchmarkEvent - " );
	    
	    Benchmark parentEntity = repository.findById(parentId).get();
	    PerformanceReport child = registry.project( PerformanceReport.class, addTo.getPerformanceReportId());
	    
	    parentEntity.getPerformanceReports().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the PerformanceReports
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Benchmark
     */
	public Benchmark removeFromPerformanceReports( UUID parentId, PerformanceReport removeFrom ) {
	    LOGGER.info("handling RemovePerformanceReportsFromBenchmarkEvent " );
	
	    Benchmark parentEntity = repository.findById(parentId).get();
	    PerformanceReport child = registry.project( PerformanceReport.class, removeFrom.getPerformanceReportId());
	    
	    parentEntity.getPerformanceReports().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the Constituents
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Benchmark
     */
    public Benchmark addToConstituents( UUID parentId, Security addTo ) {
	    LOGGER.info("handling AssignConstituentsToBenchmarkEvent - " );
	    
	    Benchmark parentEntity = repository.findById(parentId).get();
	    Security child = registry.project( Security.class, addTo.getSecurityId());
	    
	    parentEntity.getConstituents().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Constituents
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Benchmark
     */
	public Benchmark removeFromConstituents( UUID parentId, Security removeFrom ) {
	    LOGGER.info("handling RemoveConstituentsFromBenchmarkEvent " );
	
	    Benchmark parentEntity = repository.findById(parentId).get();
	    Security child = registry.project( Security.class, removeFrom.getSecurityId());
	    
	    parentEntity.getConstituents().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Benchmark via an FindBenchmarkQuery
     * @return 	query	FindBenchmarkQuery
     */
    @SuppressWarnings("unused")
    public Benchmark find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Benchmark - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Benchmarks
     *
     * @param	query	FindAllBenchmarkQuery 
     * @return 	List<Benchmark> 
     */
    @SuppressWarnings("unused")
    public List<Benchmark> findAll( FindAllBenchmarkQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Benchmark - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final BenchmarkRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(BenchmarkEntityProjector.class.getName());

}
